  // Active script — points at whichever tour is running.
  var STEPS = STEPS_DASH;

  // ─── Overlay DOM ──────────────────────────────────────────────────────
  function _ensureDom() {
    _teardownDom();
    var root = document.createElement("div");
    root.id = OVERLAY_ID;
    // Single spotlight: a transparent box positioned over the target whose
    // huge box-shadow dims everything around it. The shadow auto-covers the
    // whole screen at any size — no window.innerWidth math, so it's immune to
    // the kernel's laptop zoom (which broke the old 4-rect dim).
    var spot = document.createElement("div");
    spot.className = "_eli3_tour_spot";
    root.appendChild(spot); _els.spot = spot;
    var card = document.createElement("div");
    card.className = "_eli3_tour_card";
    root.appendChild(card); _els.card = card;
    document.body.appendChild(root); _els.root = root;
  }
  function _teardownDom() {
    var ex = document.getElementById(OVERLAY_ID);
    if (ex) ex.remove();
    _els = {};
  }
  function _setRect(el, x, y, w, h) {
    el.style.left = Math.round(x) + "px"; el.style.top = Math.round(y) + "px";
    el.style.width = Math.max(0, Math.round(w)) + "px"; el.style.height = Math.max(0, Math.round(h)) + "px";
  }
  // The kernel applies html { zoom } on laptops. The overlay lives under that
  // zoom, but getBoundingClientRect / innerWidth report VISUAL pixels — divide
  // by the zoom to convert into the overlay's coordinate space so the spotlight
  // and card land correctly. (Box-shadow handles the dim, so no width math.)
  function _z() {
    var z = 1;
    try {
      z = parseFloat(document.documentElement.style.zoom)
        || parseFloat(getComputedStyle(document.documentElement).zoom) || 1;
    } catch (_e) {}
    return (z && isFinite(z) && z > 0) ? z : 1;
  }
  function _vw() { return window.innerWidth / _z(); }
  function _vh() { return window.innerHeight / _z(); }
  function _hideSpot() { if (_els.spot) _els.spot.style.display = "none"; }
  // Full-screen backdrop, no hole — intro splash. A 0-size spot whose huge
  // box-shadow covers everything; border hidden via the _nohole class.
  function _fullDim() {
    if (!_els.spot) return;
    _els.spot.classList.add("_nohole");
    _els.spot.style.display = "block";
    _setRect(_els.spot, _vw() / 2, _vh() / 2, 0, 0);
  }
  function _centerCard() {
    var card = _els.card; if (!card) return;
    var prev = card.style.visibility;
    card.style.visibility = "hidden"; card.style.left = "-9999px"; card.style.top = "0px";
    var cw = card.offsetWidth, ch = card.offsetHeight, vw = _vw(), vh = _vh();
    card.style.left = Math.round(Math.max(8, (vw - cw) / 2)) + "px";
    card.style.top = Math.round(Math.max(8, (vh - ch) / 2)) + "px";
    card.style.visibility = prev || "";
  }
  function _showSpot(r) {
    if (!_els.spot) return;
    var z = _z(), p = 6;
    // Convert the visual rect into the overlay's (zoomed) coordinate space.
    var x = r.left / z - p, y = r.top / z - p;
    var w = r.width / z + p * 2, h = r.height / z + p * 2;
    _els.spot.classList.remove("_nohole");
    _els.spot.style.display = "block";
    _setRect(_els.spot, Math.max(0, x), Math.max(0, y), w, h);
  }
  function _placeCard(r) {
    var card = _els.card;
    var prevVis = card.style.visibility;
    card.style.visibility = "hidden"; card.style.left = "-9999px"; card.style.top = "0px";
    var cw = card.offsetWidth, ch = card.offsetHeight, m = 14;
    var z = _z(), vw = _vw(), vh = _vh();
    // Convert the visual target rect into the overlay's (zoomed) space.
    if (r) r = { left: r.left / z, top: r.top / z, right: r.right / z, bottom: r.bottom / z };
    var pos = null;
    if (_dragPos) {
      pos = { x: _dragPos.x, y: _dragPos.y };
    } else if (r) {
      var clampY = function (yy) { return Math.max(m, Math.min(vh - ch - m, yy)); };
      var clampX = function (xx) { return Math.max(m, Math.min(vw - cw - m, xx)); };
      var cands = [
        { x: r.right + m, y: clampY(r.top) },             // right
        { x: r.left - cw - m, y: clampY(r.top) },         // left
        { x: clampX(r.left), y: r.bottom + m },           // below
        { x: clampX(r.left), y: r.top - ch - m },         // above
      ];
      for (var i = 0; i < cands.length; i++) {
        var c = cands[i];
        if (c.x >= m && c.y >= m && c.x + cw <= vw - m && c.y + ch <= vh - m) { pos = c; break; }
      }
    }
    if (!pos) pos = { x: (vw - cw) / 2, y: vh - ch - m * 2 };
    pos.x = Math.max(m, Math.min(vw - cw - m, pos.x));
    pos.y = Math.max(m, Math.min(vh - ch - m, pos.y));
    card.style.left = Math.round(pos.x) + "px"; card.style.top = Math.round(pos.y) + "px";
    card.style.visibility = prevVis || "";
  }

  function _dots() {
    var out = "";
